import pypdf, docx, openpyxl, os

def read_pdf(path):
    print("=== PDF:", path)
    r = pypdf.PdfReader(path)
    for i, p in enumerate(r.pages):
        print(f"--- Page {i+1} ---")
        print(p.extract_text())

def read_docx(path):
    print("=== DOCX:", path)
    d = docx.Document(path)
    for p in d.paragraphs:
        if p.text.strip():
            print(p.text)
    for t in d.tables:
        print("--- TABLE ---")
        for row in t.rows:
            print([c.text.strip() for c in row.cells])

