import openpyxl, glob

keywords = ["108", "097", "103", "Elderpine", "Northline", "Ashford", "2023-0894", "2024-0091", "2024-0231", "2025-0044", "Grantwyck", "Cindermere", "Ravenford", "Fenwyn"]
for path in sorted(glob.glob("/filesystem/**/*.xlsx", recursive=True)):
    wb = openpyxl.load_workbook(path, data_only=True)
    for name in wb.sheetnames:
        ws = wb[name]
        for r_idx, row in enumerate(ws.iter_rows(values_only=True), 1):
            line = " | ".join(str(x) if x is not None else "" for x in row)
            if any(k.lower() in line.lower() for k in keywords):
                print(f"{path} [{name} R{r_idx}]: {line}")
